INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 1, 1, 'In the first year of King Cyrus of Persia, in order that the word of the LORD by the mouth of Jeremiah might be accomplished, the LORD stirred up the spirit of King Cyrus of Persia so that he sent a herald throughout all his kingdom, and also in a written edict declared:', 'en', 'NRSV-CE', 'End of the Babylonian Captivity'),
(15, 'Ezr', 'Ezra', 1, 2, '"Thus says King Cyrus of Persia: The LORD, the God of heaven, has given me all the kingdoms of the earth, and he has charged me to build him a house at Jerusalem in Judah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 3, 'Any of those among you who are of his people--may their God be with them!--are now permitted to go up to Jerusalem in Judah, and rebuild the house of the LORD, the God of Israel--he is the God who is in Jerusalem;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 4, 'and let all survivors, in whatever place they reside, be assisted by the people of their place with silver and gold, with goods and with animals, besides freewill offerings for the house of God in Jerusalem."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 5, 'The heads of the families of Judah and Benjamin, and the priests and the Levites--everyone whose spirit God had stirred--got ready to go up and rebuild the house of the LORD in Jerusalem.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 6, 'All their neighbors aided them with silver vessels, with gold, with goods, with animals, and with valuable gifts, besides all that was freely offered.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 7, 'King Cyrus himself brought out the vessels of the house of the LORD that Nebuchadnezzar had carried away from Jerusalem and placed in the house of his gods.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 8, 'King Cyrus of Persia had them released into the charge of Mithredath the treasurer, who counted them out to Sheshbazzar the prince of Judah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 9, 'And this was the inventory: gold basins, thirty; silver basins, one thousand; knives, twenty-nine;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 10, 'gold bowls, thirty; other silver bowls, four hundred ten; other vessels, one thousand;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 1, 11, 'the total of the gold and silver vessels was five thousand four hundred. All these Sheshbazzar brought up, when the exiles were brought up from Babylonia to Jerusalem.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 2, 1, 'Now these were the people of the province who came from those captive exiles whom King Nebuchadnezzar of Babylon had carried captive to Babylonia; they returned to Jerusalem and Judah, all to their own towns.', 'en', 'NRSV-CE', 'List of the Returned Exiles'),
(15, 'Ezr', 'Ezra', 2, 2, 'They came with Zerubbabel, Jeshua, Nehemiah, Seraiah, Reelaiah, Mordecai, Bilshan, Mispar, Bigvai, Rehum, and Baanah.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 3, 1, 'When the seventh month came, and the Israelites were in the towns, the people gathered together in Jerusalem.', 'en', 'NRSV-CE', 'Worship Restored at Jerusalem'),
(15, 'Ezr', 'Ezra', 3, 2, 'Then Jeshua son of Jozadak, with his fellow priests, and Zerubbabel son of Shealtiel with his kin set out to build the altar of the God of Israel, to offer burnt offerings on it, as prescribed in the law of Moses the man of God.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 3, 'They set up the altar on its foundation, because they were in dread of the neighboring peoples, and they offered burnt offerings upon it to the LORD, morning and evening.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 4, 'And they kept the festival of booths, as prescribed, and offered the daily burnt offerings by number according to the ordinance, as required for each day,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 5, 'and after that the regular burnt offerings, the offerings at the new moon and at all the sacred festivals of the LORD, and the offerings of everyone who made a freewill offering to the LORD.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 6, 'From the first day of the seventh month they began to offer burnt offerings to the LORD. But the foundation of the temple of the LORD was not yet laid.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 7, 'So they gave money to the masons and the carpenters, and food, drink, and oil to the Sidonians and the Tyrians to bring cedar trees from Lebanon to the sea, to Joppa, according to the grant that they had from King Cyrus of Persia.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 8, 'In the second year after their arrival at the house of God at Jerusalem, in the second month, Zerubbabel son of Shealtiel and Jeshua son of Jozadak made a beginning, together with the rest of their people, the priests and the Levites and all who had come to Jerusalem from the captivity. They appointed the Levites, from twenty years old and upward, to have the oversight of the work on the house of the LORD.', 'en', 'NRSV-CE', 'Foundation Laid for the Temple'),
(15, 'Ezr', 'Ezra', 3, 9, 'And Jeshua with his sons and his kin, and Kadmiel and his sons, Binnui and Hodaviah along with the sons of Henadad, the Levites, their sons and kin, together took charge of the workers in the house of God.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 10, 'When the builders laid the foundation of the temple of the LORD, the priests in their vestments were stationed to praise the LORD with trumpets, and the Levites, the sons of Asaph, with cymbals, according to the directions of King David of Israel;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 3, 11, 'and they sang responsively, praising and giving thanks to the LORD,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 4, 1, 'When the adversaries of Judah and Benjamin heard that the returned exiles were building a temple to the LORD, the God of Israel,', 'en', 'NRSV-CE', 'Resistance to Rebuilding the Temple'),
(15, 'Ezr', 'Ezra', 4, 2, 'they approached Zerubbabel and the heads of families and said to them, "Let us build with you, for we worship your God as you do, and we have been sacrificing to him ever since the days of King Esar-haddon of Assyria who brought us here."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 3, 'But Zerubbabel, Jeshua, and the rest of the heads of families in Israel said to them, "You shall have no part with us in building a house to our God; but we alone will build to the LORD, the God of Israel, as King Cyrus of Persia has commanded us."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 4, 'Then the people of the land discouraged the people of Judah, and made them afraid to build,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 5, 'and they bribed officials to frustrate their plan throughout the reign of King Cyrus of Persia and until the reign of King Darius of Persia.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 6, 'In the reign of Ahasuerus, in his accession year, they wrote an accusation against the inhabitants of Judah and Jerusalem.', 'en', 'NRSV-CE', 'Rebuilding of Jerusalem Opposed'),
(15, 'Ezr', 'Ezra', 4, 7, 'And in the days of Artaxerxes, Bishlam and Mithredath and Tabeel and the rest of their associates wrote to King Artaxerxes of Persia; the letter was written in Aramaic and translated.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 8, 'Rehum the royal deputy and Shimshai the scribe wrote a letter against Jerusalem to King Artaxerxes as follows', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 9, '(then Rehum the royal deputy, Shimshai the scribe, and the rest of their associates, the judges, the envoys, the officials, the Persians, the people of Erech, the Babylonians, the people of Susa, that is, the Elamites,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 10, 'and the rest of the nations whom the great and noble Osnappar deported and settled in the cities of Samaria and in the rest of the province Beyond the River wrote--and now', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 4, 11, 'this is a copy of the letter that they sent):
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 5, 1, 'Now the prophets, Haggai and Zechariah son of Iddo, prophesied to the Jews who were in Judah and Jerusalem, in the name of the God of Israel who was over them.', 'en', 'NRSV-CE', 'Restoration of the Temple Resumed'),
(15, 'Ezr', 'Ezra', 5, 2, 'Then Zerubbabel son of Shealtiel and Jeshua son of Jozadak set out to rebuild the house of God in Jerusalem; and with them were the prophets of God, helping them.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 3, 'At the same time Tattenai the governor of the province Beyond the River and Shethar-bozenai and their associates came to them and spoke to them thus, "Who gave you a decree to build this house and to finish this structure?"', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 4, 'They also asked them this, "What are the names of the men who are building this building?"', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 5, 'But the eye of their God was upon the elders of the Jews, and they did not stop them until a report reached Darius and then answer was returned by letter in reply to it.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 6, 'The copy of the letter that Tattenai the governor of the province Beyond the River and Shethar-bozenai and his associates the envoys who were in the province Beyond the River sent to King Darius;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 7, 'they sent him a report, in which was written as follows: "To Darius the king, all peace!', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 8, 'May it be known to the king that we went to the province of Judah, to the house of the great God. It is being built of hewn stone, and timber is laid in the walls; this work is being done diligently and prospers in their hands.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 9, 'Then we spoke to those elders and asked them, "Who gave you a decree to build this house and to finish this structure?"', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 10, 'We also asked them their names, for your information, so that we might write down the names of the men at their head.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 11, 'This was their reply to us: "We are the servants of the God of heaven and earth, and we are rebuilding the house that was built many years ago, which a great king of Israel built and finished.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 12, 'But because our ancestors had angered the God of heaven, he gave them into the hand of King Nebuchadnezzar of Babylon, the Chaldean, who destroyed this house and carried away the people to Babylonia.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 13, 'However, King Cyrus of Babylon, in the first year of his reign, made a decree that this house of God should be rebuilt.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 14, 'Moreover, the gold and silver vessels of the house of God, which Nebuchadnezzar had taken out of the temple in Jerusalem and had brought into the temple of Babylon, these King Cyrus took out of the temple of Babylon, and they were delivered to a man named Sheshbazzar, whom he had made governor.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 15, 'He said to him, "Take these vessels; go and put them in the temple in Jerusalem, and let the house of God be rebuilt on its site."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 16, 'Then this Sheshbazzar came and laid the foundations of the house of God in Jerusalem; and from that time until now it has been under construction, and it is not yet finished."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 5, 17, 'And now, if it seems good to the king, have a search made in the royal archives there in Babylon, to see whether a decree was issued by King Cyrus for the rebuilding of this house of God in Jerusalem. Let the king send us his pleasure in this matter."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 6, 1, 'Then King Darius made a decree, and they searched the archives where the documents were stored in Babylon.', 'en', 'NRSV-CE', 'The Decree of Darius'),
(15, 'Ezr', 'Ezra', 6, 2, 'But it was in Ecbatana, the capital in the province of Media, that a scroll was found on which this was written: "A record.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 3, 'In the first year of his reign, King Cyrus issued a decree: Concerning the house of God at Jerusalem, let the house be rebuilt, the place where sacrifices are offered and burnt offerings are brought; its height shall be sixty cubits and its width sixty cubits,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 4, 'with three courses of hewn stones and one course of timber; let the cost be paid from the royal treasury.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 5, 'Moreover, let the gold and silver vessels of the house of God, which Nebuchadnezzar took out of the temple in Jerusalem and brought to Babylon, be restored and brought back to the temple in Jerusalem, each to its place; you shall put them in the house of God."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 6, '"Now you, Tattenai, governor of the province Beyond the River, Shethar-bozenai, and you, their associates, the envoys in the province Beyond the River, keep away;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 7, 'let the work on this house of God alone; let the governor of the Jews and the elders of the Jews rebuild this house of God on its site.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 8, 'Moreover I make a decree regarding what you shall do for these elders of the Jews for the rebuilding of this house of God: the cost is to be paid to these people, in full and without delay, from the royal revenue, the tribute of the province Beyond the River.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 9, 'Whatever is needed--young bulls, rams, or sheep for burnt offerings to the God of heaven, wheat, salt, wine, or oil, as the priests in Jerusalem require--let that be given to them day by day without fail,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 10, 'so that they may offer pleasing sacrifices to the God of heaven, and pray for the life of the king and his children.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 11, 'Furthermore I decree that if anyone alters this edict, a beam shall be pulled out of the house of the perpetrator, who then shall be impaled on it. The house shall be made a dunghill.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 12, 'May the God who has established his name there overthrow any king or people that shall put forth a hand to alter this, or to destroy this house of God in Jerusalem. I, Darius, make a decree; let it be done with all diligence."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 13, 'Then, according to the word sent by King Darius, Tattenai, the governor of the province Beyond the River, Shethar-bozenai, and their associates did with all diligence what King Darius had ordered.', 'en', 'NRSV-CE', 'Completion and Dedication of the Temple'),
(15, 'Ezr', 'Ezra', 6, 14, 'So the elders of the Jews built and prospered, through the prophesying of the prophet Haggai and Zechariah son of Iddo. They finished their building by command of the God of Israel and by decree of Cyrus, Darius, and King Artaxerxes of Persia;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 15, 'and this house was finished on the third day of the month of Adar, in the sixth year of the reign of King Darius.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 16, 'The people of Israel, the priests and the Levites, and the rest of the returned exiles, celebrated the dedication of this house of God with joy.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 17, 'They offered at the dedication of this house of God one hundred bulls, two hundred rams, four hundred lambs, and as a sin offering for all Israel, twelve male goats, according to the number of the tribes of Israel.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 18, 'Then they set the priests in their divisions and the Levites in their courses for the service of God at Jerusalem, as it is written in the book of Moses.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 19, 'On the fourteenth day of the first month the returned exiles kept the passover.', 'en', 'NRSV-CE', 'The Passover Celebrated'),
(15, 'Ezr', 'Ezra', 6, 20, 'For both the priests and the Levites had purified themselves; all of them were clean. So they killed the passover lamb for all the returned exiles, for their fellow priests, and for themselves.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 21, 'It was eaten by the people of Israel who had returned from exile, and also by all who had joined them and separated themselves from the pollutions of the nations of the land to worship the LORD, the God of Israel.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 6, 22, 'With joy they celebrated the festival of unleavened bread seven days; for the LORD had made them joyful, and had turned the heart of the king of Assyria to them, so that he aided them in the work on the house of God, the God of Israel.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 7, 1, 'After this, in the reign of King Artaxerxes of Persia, Ezra son of Seraiah, son of Azariah, son of Hilkiah,', 'en', 'NRSV-CE', 'The Coming and Work of Ezra'),
(15, 'Ezr', 'Ezra', 7, 2, 'son of Shallum, son of Zadok, son of Ahitub,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 3, 'son of Amariah, son of Azariah, son of Meraioth,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 4, 'son of Zerahiah, son of Uzzi, son of Bukki,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 5, 'son of Abishua, son of Phinehas, son of Eleazar, son of the chief priest Aaron--', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 6, 'this Ezra went up from Babylonia. He was a scribe skilled in the law of Moses that the LORD the God of Israel had given; and the king granted him all that he asked, for the hand of the LORD his God was upon him.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 7, 'Some of the people of Israel, and some of the priests and Levites, the singers and gatekeepers, and the temple servants also went up to Jerusalem, in the seventh year of King Artaxerxes.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 8, 'They came to Jerusalem in the fifth month, which was in the seventh year of the king.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 9, 'On the first day of the first month the journey up from Babylon was begun, and on the first day of the fifth month he came to Jerusalem, for the gracious hand of his God was upon him.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 10, 'For Ezra had set his heart to study the law of the LORD, and to do it, and to teach the statutes and ordinances in Israel.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 11, 'This is a copy of the letter that King Artaxerxes gave to the priest Ezra, the scribe, a scholar of the text of the commandments of the LORD and his statutes for Israel:', 'en', 'NRSV-CE', 'The Letter of Artaxerxes to Ezra'),
(15, 'Ezr', 'Ezra', 7, 12, '"Artaxerxes, king of kings, to the priest Ezra, the scribe of the law of the God of heaven: Peace. And now', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 13, 'I decree that any of the people of Israel or their priests or Levites in my kingdom who freely offers to go to Jerusalem may go with you.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 14, 'For you are sent by the king and his seven counselors to make inquiries about Judah and Jerusalem according to the law of your God, which is in your hand,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 15, 'and also to convey the silver and gold that the king and his counselors have freely offered to the God of Israel, whose dwelling is in Jerusalem,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 16, 'with all the silver and gold that you shall find in the whole province of Babylonia, and with the freewill offerings of the people and the priests, given willingly for the house of their God in Jerusalem.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 17, 'With this money, then, you shall with all diligence buy bulls, rams, and lambs, and their grain offerings and their drink offerings, and you shall offer them on the altar of the house of your God in Jerusalem.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 18, 'Whatever seems good to you and your colleagues to do with the rest of the silver and gold, you may do, according to the will of your God.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 19, 'The vessels that have been given you for the service of the house of your God, you shall deliver before the God of Jerusalem.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 20, 'And whatever else is required for the house of your God, which you are responsible for providing, you may provide out of the king"s treasury.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 21, '"I, King Artaxerxes, decree to all the treasurers in the province Beyond the River: Whatever the priest Ezra, the scribe of the law of the God of heaven, requires of you, let it be done with all diligence,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 22, 'up to one hundred talents of silver, one hundred cors of wheat, one hundred baths of wine, one hundred baths of oil, and unlimited salt.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 23, 'Whatever is commanded by the God of heaven, let it be done with zeal for the house of the God of heaven, or wrath will come upon the realm of the king and his heirs.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 24, 'We also notify you that it shall not be lawful to impose tribute, custom, or toll on any of the priests, the Levites, the singers, the doorkeepers, the temple servants, or other servants of this house of God.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 25, '"And you, Ezra, according to the God-given wisdom you possess, appoint magistrates and judges who may judge all the people in the province Beyond the River who know the laws of your God; and you shall teach those who do not know them.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 26, 'All who will not obey the law of your God and the law of the king, let judgment be strictly executed on them, whether for death or for banishment or for confiscation of their goods or for imprisonment."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 27, 'Blessed be the LORD, the God of our ancestors, who put such a thing as this into the heart of the king to glorify the house of the LORD in Jerusalem,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 7, 28, 'and who extended to me steadfast love before the king and his counselors, and before all the king"s mighty officers. I took courage, for the hand of the LORD my God was upon me, and I gathered leaders from Israel to go up with me.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 8, 1, 'These are their family heads, and this is the genealogy of those who went up with me from Babylonia, in the reign of King Artaxerxes:', 'en', 'NRSV-CE', 'Heads of Families Who Returned with Ezra'),
(15, 'Ezr', 'Ezra', 8, 2, 'Of the descendants of Phinehas, Gershom. Of Ithamar, Daniel. Of David, Hattush,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 3, 'of the descendants of Shecaniah. Of Parosh, Zechariah, with whom were registered one hundred fifty males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 4, 'Of the descendants of Pahath-moab, Eliehoenai son of Zerahiah, and with him two hundred males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 5, 'Of the descendants of Zattu, Shecaniah son of Jahaziel, and with him three hundred males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 6, 'Of the descendants of Adin, Ebed son of Jonathan, and with him fifty males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 7, 'Of the descendants of Elam, Jeshaiah son of Athaliah, and with him seventy males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 8, 'Of the descendants of Shephatiah, Zebadiah son of Michael, and with him eighty males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 9, 'Of the descendants of Joab, Obadiah son of Jehiel, and with him two hundred eighteen males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 10, 'Of the descendants of Bani, Shelomith son of Josiphiah, and with him one hundred sixty males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 11, 'Of the descendants of Bebai, Zechariah son of Bebai, and with him twenty-eight males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 12, 'Of the descendants of Azgad, Johanan son of Hakkatan, and with him one hundred ten males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 13, 'Of the descendants of Adonikam, those who came later, their names being Eliphelet, Jeuel, and Shemaiah, and with them sixty males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 14, 'Of the descendants of Bigvai, Uthai and Zaccur, and with them seventy males.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 15, 'I gathered them by the river that runs to Ahava, and there we camped three days. As I reviewed the people and the priests, I found there none of the descendants of Levi.', 'en', 'NRSV-CE', 'Servants for the Temple'),
(15, 'Ezr', 'Ezra', 8, 16, 'Then I sent for Eliezer, Ariel, Shemaiah, Elnathan, Jarib, Elnathan, Nathan, Zechariah, and Meshullam, who were leaders, and for Joiarib and Elnathan, who were wise,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 17, 'and sent them to Iddo, the leader at the place called Casiphia, telling them what to say to Iddo and his colleagues the temple servants at Casiphia, namely, to send us ministers for the house of our God.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 18, 'Since the gracious hand of our God was upon us, they brought us a man of discretion, of the descendants of Mahli son of Levi son of Israel, namely Sherebiah, with his sons and kin, eighteen;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 19, 'also Hashabiah and with him Jeshaiah of the descendants of Merari, with his kin and their sons, twenty;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 20, 'besides two hundred twenty of the temple servants, whom David and his officials had set apart to attend the Levites. These were all mentioned by name.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 21, 'Then I proclaimed a fast there, at the river Ahava, that we might deny ourselves before our God, to seek from him a safe journey for ourselves, our children, and all our possessions.', 'en', 'NRSV-CE', 'Fasting and Prayer for Protection'),
(15, 'Ezr', 'Ezra', 8, 22, 'For I was ashamed to ask the king for a band of soldiers and cavalry to protect us against the enemy on our way, since we had told the king that the hand of our God is gracious to all who seek him, but his power and his wrath are against all who forsake him.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 23, 'So we fasted and petitioned our God for this, and he listened to our entreaty.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 24, 'Then I set apart twelve of the leading priests: Sherebiah, Hashabiah, and ten of their kin with them.', 'en', 'NRSV-CE', 'Gifts for the Temple'),
(15, 'Ezr', 'Ezra', 8, 25, 'And I weighed out to them the silver and the gold and the vessels, the offering for the house of our God that the king, his counselors, his lords, and all Israel there present had offered;', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 26, 'I weighed out into their hand six hundred fifty talents of silver, and one hundred silver vessels worth... talents, and one hundred talents of gold,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 27, 'twenty gold bowls worth a thousand darics, and two vessels of fine polished bronze as precious as gold.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 28, 'And I said to them, "You are holy to the LORD, and the vessels are holy; and the silver and the gold are a freewill offering to the LORD, the God of your ancestors.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 29, 'Guard them and keep them until you weigh them before the chief priests and the Levites and the heads of families in Israel at Jerusalem, within the chambers of the house of the LORD."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 30, 'So the priests and the Levites took over the silver, the gold, and the vessels as they were weighed out, to bring them to Jerusalem, to the house of our God.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 31, 'Then we left the river Ahava on the twelfth day of the first month, to go to Jerusalem; the hand of our God was upon us, and he delivered us from the hand of the enemy and from ambushes along the way.', 'en', 'NRSV-CE', 'The Return to Jerusalem'),
(15, 'Ezr', 'Ezra', 8, 32, 'We came to Jerusalem and remained there three days.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 33, 'On the fourth day, within the house of our God, the silver, the gold, and the vessels were weighed into the hands of the priest Meremoth son of Uriah, and with him was Eleazar son of Phinehas, and with them were the Levites, Jozabad son of Jeshua and Noadiah son of Binnui.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 34, 'The total was counted and weighed, and the weight of everything was recorded.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 35, 'At that time those who had come from captivity, the returned exiles, offered burnt offerings to the God of Israel, twelve bulls for all Israel, ninety-six rams, seventy-seven lambs, and as a sin offering twelve male goats; all this was a burnt offering to the LORD.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 8, 36, 'They also delivered the king"s commissions to the king"s satraps and to the governors of the province Beyond the River; and they supported the people and the house of God.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 9, 1, 'After these things had been done, the officials approached me and said, "The people of Israel, the priests, and the Levites have not separated themselves from the peoples of the lands with their abominations, from the Canaanites, the Hittites, the Perizzites, the Jebusites, the Ammonites, the Moabites, the Egyptians, and the Amorites.', 'en', 'NRSV-CE', 'Denunciation of Mixed Marriages'),
(15, 'Ezr', 'Ezra', 9, 2, 'For they have taken some of their daughters as wives for themselves and for their sons. Thus the holy seed has mixed itself with the peoples of the lands, and in this faithlessness the officials and leaders have led the way."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 9, 3, 'When I heard this, I tore my garment and my mantle, and pulled hair from my head and beard, and sat appalled.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 9, 4, 'Then all who trembled at the words of the God of Israel, because of the faithlessness of the returned exiles, gathered around me while I sat appalled until the evening sacrifice.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 9, 5, 'At the evening sacrifice I got up from my fasting, with my garments and my mantle torn, and fell on my knees, spread out my hands to the LORD my God,', 'en', 'NRSV-CE', 'Ezra"s Prayer'),
(15, 'Ezr', 'Ezra', 9, 6, 'and said,
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(15, 'Ezr', 'Ezra', 10, 1, 'While Ezra prayed and made confession, weeping and throwing himself down before the house of God, a very great assembly of men, women, and children gathered to him out of Israel; the people also wept bitterly.', 'en', 'NRSV-CE', 'The People"s Response'),
(15, 'Ezr', 'Ezra', 10, 2, 'Shecaniah son of Jehiel, of the descendants of Elam, addressed Ezra, saying, "We have broken faith with our God and have married foreign women from the peoples of the land, but even now there is hope for Israel in spite of this.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 3, 'So now let us make a covenant with our God to send away all these wives and their children, according to the counsel of my lord and of those who tremble at the commandment of our God; and let it be done according to the law.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 4, 'Take action, for it is your duty, and we are with you; be strong, and do it."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 5, 'Then Ezra stood up and made the leading priests, the Levites, and all Israel swear that they would do as had been said. So they swore.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 6, 'Then Ezra withdrew from before the house of God, and went to the chamber of Jehohanan son of Eliashib, where he spent the night. He did not eat bread or drink water, for he was mourning over the faithlessness of the exiles.', 'en', 'NRSV-CE', 'Foreign Wives and Their Children Rejected'),
(15, 'Ezr', 'Ezra', 10, 7, 'They made a proclamation throughout Judah and Jerusalem to all the returned exiles that they should assemble at Jerusalem,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 8, 'and that if any did not come within three days, by order of the officials and the elders all their property should be forfeited, and they themselves banned from the congregation of the exiles.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 9, 'Then all the people of Judah and Benjamin assembled at Jerusalem within the three days; it was the ninth month, on the twentieth day of the month. All the people sat in the open square before the house of God, trembling because of this matter and because of the heavy rain.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 10, 'Then Ezra the priest stood up and said to them, "You have trespassed and married foreign women, and so increased the guilt of Israel.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 11, 'Now make confession to the LORD the God of your ancestors, and do his will; separate yourselves from the peoples of the land and from the foreign wives."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 12, 'Then all the assembly answered with a loud voice, "It is so; we must do as you have said.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 13, 'But the people are many, and it is a time of heavy rain; we cannot stand in the open. Nor is this a task for one day or for two, for many of us have transgressed in this matter.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 14, 'Let our officials represent the whole assembly, and let all in our towns who have taken foreign wives come at appointed times, and with them the elders and judges of every town, until the fierce wrath of our God on this account is averted from us."', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 15, 'Only Jonathan son of Asahel and Jahzeiah son of Tikvah opposed this, and Meshullam and Shabbethai the Levites supported them.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 16, 'Then the returned exiles did so. Ezra the priest selected men, heads of families, according to their families, each of them designated by name. On the first day of the tenth month they sat down to examine the matter.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 17, 'By the first day of the first month they had come to the end of all the men who had married foreign women.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 18, 'There were found of the descendants of the priests who had married foreign women, of the descendants of Jeshua son of Jozadak and his brothers: Maaseiah, Eliezer, Jarib, and Gedaliah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 19, 'They pledged themselves to send away their wives, and their guilt offering was a ram of the flock for their guilt.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 20, 'Of the descendants of Immer: Hanani and Zebadiah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 21, 'Of the descendants of Harim: Maaseiah, Elijah, Shemaiah, Jehiel, and Uzziah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 22, 'Of the descendants of Pashhur: Elioenai, Maaseiah, Ishmael, Nethanel, Jozabad, and Elasah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 23, 'Of the Levites: Jozabad, Shimei, Kelaiah (that is, Kelita), Pethahiah, Judah, and Eliezer.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 24, 'Of the singers: Eliashib. Of the gatekeepers: Shallum, Telem, and Uri.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 25, 'And of Israel: of the descendants of Parosh: Ramiah, Izziah, Malchijah, Mijamin, Eleazar, Hashabiah, and Benaiah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 26, 'Of the descendants of Elam: Mattaniah, Zechariah, Jehiel, Abdi, Jeremoth, and Elijah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 27, 'Of the descendants of Zattu: Elioenai, Eliashib, Mattaniah, Jeremoth, Zabad, and Aziza.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 28, 'Of the descendants of Bebai: Jehohanan, Hananiah, Zabbai, and Athlai.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 29, 'Of the descendants of Bani: Meshullam, Malluch, Adaiah, Jashub, Sheal, and Jeremoth.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 30, 'Of the descendants of Pahath-moab: Adna, Chelal, Benaiah, Maaseiah, Mattaniah, Bezalel, Binnui, and Manasseh.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 31, 'Of the descendants of Harim: Eliezer, Isshijah, Malchijah, Shemaiah, Shimeon,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 32, 'Benjamin, Malluch, and Shemariah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 33, 'Of the descendants of Hashum: Mattenai, Mattattah, Zabad, Eliphelet, Jeremai, Manasseh, and Shimei.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 34, 'Of the descendants of Bani: Maadai, Amram, Uel,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 35, 'Benaiah, Bedeiah, Cheluhi,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 36, 'Vaniah, Meremoth, Eliashib,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 37, 'Mattaniah, Mattenai, and Jaasu.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 38, 'Of the descendants of Binnui: Shimei,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 39, 'Shelemiah, Nathan, Adaiah,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 40, 'Machnadebai, Shashai, Sharai,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 41, 'Azarel, Shelemiah, Shemariah,', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 42, 'Shallum, Amariah, and Joseph.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 43, 'Of the descendants of Nebo: Jeiel, Mattithiah, Zabad, Zebina, Jaddai, Joel, and Benaiah.', 'en', 'NRSV-CE', NULL),
(15, 'Ezr', 'Ezra', 10, 44, 'All these had married foreign women, and they sent them away with their children.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 1, 1, 'The words of Nehemiah son of Hacaliah. In the month of Chislev, in the twentieth year, while I was in Susa the capital,', 'en', 'NRSV-CE', 'Nehemiah Prays for His People'),
(16, 'Neh', 'Nehemiah', 1, 2, 'one of my brothers, Hanani, came with certain men from Judah; and I asked them about the Jews that survived, those who had escaped the captivity, and about Jerusalem.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 3, 'They replied, "The survivors there in the province who escaped captivity are in great trouble and shame; the wall of Jerusalem is broken down, and its gates have been destroyed by fire."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 4, 'When I heard these words I sat down and wept, and mourned for days, fasting and praying before the God of heaven.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 5, 'I said, "O LORD God of heaven, the great and awesome God who keeps covenant and steadfast love with those who love him and keep his commandments;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 6, 'let your ear be attentive and your eyes open to hear the prayer of your servant that I now pray before you day and night for your servants, the people of Israel, confessing the sins of the people of Israel, which we have sinned against you. Both I and my family have sinned.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 7, 'We have offended you deeply, failing to keep the commandments, the statutes, and the ordinances that you commanded your servant Moses.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 8, 'Remember the word that you commanded your servant Moses, "If you are unfaithful, I will scatter you among the peoples;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 9, 'but if you return to me and keep my commandments and do them, though your outcasts are under the farthest skies, I will gather them from there and bring them to the place at which I have chosen to establish my name."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 10, 'They are your servants and your people, whom you redeemed by your great power and your strong hand.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 1, 11, 'O Lord, let your ear be attentive to the prayer of your servant, and to the prayer of your servants who delight in revering your name. Give success to your servant today, and grant him mercy in the sight of this man!"
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 2, 1, 'In the month of Nisan, in the twentieth year of King Artaxerxes, when wine was served him, I carried the wine and gave it to the king. Now, I had never been sad in his presence before.', 'en', 'NRSV-CE', 'Nehemiah Sent to Judah'),
(16, 'Neh', 'Nehemiah', 2, 2, 'So the king said to me, "Why is your face sad, since you are not sick? This can only be sadness of the heart." Then I was very much afraid.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 3, 'I said to the king, "May the king live forever! Why should my face not be sad, when the city, the place of my ancestors" graves, lies waste, and its gates have been destroyed by fire?"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 4, 'Then the king said to me, "What do you request?" So I prayed to the God of heaven.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 5, 'Then I said to the king, "If it pleases the king, and if your servant has found favor with you, I ask that you send me to Judah, to the city of my ancestors" graves, so that I may rebuild it."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 6, 'The king said to me (the queen also was sitting beside him), "How long will you be gone, and when will you return?" So it pleased the king to send me, and I set him a date.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 7, 'Then I said to the king, "If it pleases the king, let letters be given me to the governors of the province Beyond the River, that they may grant me passage until I arrive in Judah;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 8, 'and a letter to Asaph, the keeper of the king"s forest, directing him to give me timber to make beams for the gates of the temple fortress, and for the wall of the city, and for the house that I shall occupy." And the king granted me what I asked, for the gracious hand of my God was upon me.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 9, 'Then I came to the governors of the province Beyond the River, and gave them the king"s letters. Now the king had sent officers of the army and cavalry with me.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 10, 'When Sanballat the Horonite and Tobiah the Ammonite official heard this, it displeased them greatly that someone had come to seek the welfare of the people of Israel.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 11, 'So I came to Jerusalem and was there for three days.', 'en', 'NRSV-CE', 'Nehemiah"s Inspection of the Walls'),
(16, 'Neh', 'Nehemiah', 2, 12, 'Then I got up during the night, I and a few men with me; I told no one what my God had put into my heart to do for Jerusalem. The only animal I took was the animal I rode.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 13, 'I went out by night by the Valley Gate past the Dragon"s Spring and to the Dung Gate, and I inspected the walls of Jerusalem that had been broken down and its gates that had been destroyed by fire.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 14, 'Then I went on to the Fountain Gate and to the King"s Pool; but there was no place for the animal I was riding to continue.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 15, 'So I went up by way of the valley by night and inspected the wall. Then I turned back and entered by the Valley Gate, and so returned.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 16, 'The officials did not know where I had gone or what I was doing; I had not yet told the Jews, the priests, the nobles, the officials, and the rest that were to do the work.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 17, 'Then I said to them, "You see the trouble we are in, how Jerusalem lies in ruins with its gates burned. Come, let us rebuild the wall of Jerusalem, so that we may no longer suffer disgrace."', 'en', 'NRSV-CE', 'Decision to Restore the Walls'),
(16, 'Neh', 'Nehemiah', 2, 18, 'I told them that the hand of my God had been gracious upon me, and also the words that the king had spoken to me. Then they said, "Let us start building!" So they committed themselves to the common good.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 19, 'But when Sanballat the Horonite and Tobiah the Ammonite official, and Geshem the Arab heard of it, they mocked and ridiculed us, saying, "What is this that you are doing? Are you rebelling against the king?"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 2, 20, 'Then I replied to them, "The God of heaven is the one who will give us success, and we his servants are going to start building; but you have no share or claim or historic right in Jerusalem."', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 3, 1, 'Then the high priest Eliashib set to work with his fellow priests and rebuilt the Sheep Gate. They consecrated it and set up its doors; they consecrated it as far as the Tower of the Hundred and as far as the Tower of Hananel.', 'en', 'NRSV-CE', 'Organization of the Work'),
(16, 'Neh', 'Nehemiah', 3, 2, 'And the men of Jericho built next to him. And next to them Zaccur son of Imri built.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 3, 'The sons of Hassenaah built the Fish Gate; they laid its beams and set up its doors, its bolts, and its bars.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 4, 'Next to them Meremoth son of Uriah son of Hakkoz made repairs. Next to them Meshullam son of Berechiah son of Meshezabel made repairs. Next to them Zadok son of Baana made repairs.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 5, 'Next to them the Tekoites made repairs; but their nobles would not put their shoulders to the work of their Lord.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 6, 'Joiada son of Paseah and Meshullam son of Besodeiah repaired the Old Gate; they laid its beams and set up its doors, its bolts, and its bars.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 7, 'Next to them repairs were made by Melatiah the Gibeonite and Jadon the Meronothite--the men of Gibeon and of Mizpah--who were under the jurisdiction of the governor of the province Beyond the River.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 8, 'Next to them Uzziel son of Harhaiah, one of the goldsmiths, made repairs. Next to him Hananiah, one of the perfumers, made repairs; and they restored Jerusalem as far as the Broad Wall.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 9, 'Next to them Rephaiah son of Hur, ruler of half the district of Jerusalem, made repairs.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 10, 'Next to them Jedaiah son of Harumaph made repairs opposite his house; and next to him Hattush son of Hashabneiah made repairs.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 11, 'Malchijah son of Harim and Hasshub son of Pahath-moab repaired another section and the Tower of the Ovens.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 12, 'Next to him Shallum son of Hallohesh, ruler of half the district of Jerusalem, made repairs, he and his daughters.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 13, 'Hanun and the inhabitants of Zanoah repaired the Valley Gate; they rebuilt it and set up its doors, its bolts, and its bars, and repaired a thousand cubits of the wall, as far as the Dung Gate.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 14, 'Malchijah son of Rechab, ruler of the district of Beth-haccherem, repaired the Dung Gate; he rebuilt it and set up its doors, its bolts, and its bars.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 15, 'And Shallum son of Col-hozeh, ruler of the district of Mizpah, repaired the Fountain Gate; he rebuilt it and covered it and set up its doors, its bolts, and its bars; and he built the wall of the Pool of Shelah of the king"s garden, as far as the stairs that go down from the City of David.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 16, 'After him Nehemiah son of Azbuk, ruler of half the district of Beth-zur, repaired from a point opposite the graves of David, as far as the artificial pool and the house of the warriors.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 17, 'After him the Levites made repairs: Rehum son of Bani; next to him Hashabiah, ruler of half the district of Keilah, made repairs for his district.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 18, 'After him their kin made repairs: Binnui, son of Henadad, ruler of half the district of Keilah;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 19, 'next to him Ezer son of Jeshua, ruler of Mizpah, repaired another section opposite the ascent to the armory at the Angle.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 20, 'After him Baruch son of Zabbai repaired another section from the Angle to the door of the house of the high priest Eliashib.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 21, 'After him Meremoth son of Uriah son of Hakkoz repaired another section from the door of the house of Eliashib to the end of the house of Eliashib.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 22, 'After him the priests, the men of the surrounding area, made repairs.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 23, 'After them Benjamin and Hasshub made repairs opposite their house. After them Azariah son of Maaseiah son of Ananiah made repairs beside his own house.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 24, 'After him Binnui son of Henadad repaired another section, from the house of Azariah to the Angle and to the corner.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 25, 'Palal son of Uzai repaired opposite the Angle and the tower projecting from the upper house of the king at the court of the guard. After him Pedaiah son of Parosh', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 26, 'and the temple servants living on Ophel made repairs up to a point opposite the Water Gate on the east and the projecting tower.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 27, 'After him the Tekoites repaired another section opposite the great projecting tower as far as the wall of Ophel.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 28, 'Above the Horse Gate the priests made repairs, each one opposite his own house.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 29, 'After them Zadok son of Immer made repairs opposite his own house. After him Shemaiah son of Shecaniah, the keeper of the East Gate, made repairs.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 30, 'After him Hananiah son of Shelemiah and Hanun sixth son of Zalaph repaired another section. After him Meshullam son of Berechiah made repairs opposite his living quarters.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 31, 'After him Malchijah, one of the goldsmiths, made repairs as far as the house of the temple servants and of the merchants, opposite the Muster Gate, and to the upper room of the corner.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 3, 32, 'And between the upper room of the corner and the Sheep Gate the goldsmiths and the merchants made repairs.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 4, 1, 'Now when Sanballat heard that we were building the wall, he was angry and greatly enraged, and he mocked the Jews.', 'en', 'NRSV-CE', 'Hostile Plots Thwarted'),
(16, 'Neh', 'Nehemiah', 4, 2, 'He said in the presence of his associates and of the army of Samaria, "What are these feeble Jews doing? Will they restore things? Will they sacrifice? Will they finish it in a day? Will they revive the stones out of the heaps of rubbish--and burned ones at that?"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 3, 'Tobiah the Ammonite was beside him, and he said, "That stone wall they are building--any fox going up on it would break it down!"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 4, 'Hear, O our God, for we are despised; turn their taunt back on their own heads, and give them over as plunder in a land of captivity.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 5, 'Do not cover their guilt, and do not let their sin be blotted out from your sight; for they have hurled insults in the face of the builders.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 6, 'So we rebuilt the wall, and all the wall was joined together to half its height; for the people had a mind to work.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 7, 'But when Sanballat and Tobiah and the Arabs and the Ammonites and the Ashdodites heard that the repairing of the walls of Jerusalem was going forward and the gaps were beginning to be closed, they were very angry,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 8, 'and all plotted together to come and fight against Jerusalem and to cause confusion in it.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 9, 'So we prayed to our God, and set a guard as a protection against them day and night.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 10, 'But Judah said, "The strength of the burden bearers is failing, and there is too much rubbish so that we are unable to work on the wall."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 11, 'And our enemies said, "They will not know or see anything before we come upon them and kill them and stop the work."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 12, 'When the Jews who lived near them came, they said to us ten times, "From all the places where they live they will come up against us."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 13, 'So in the lowest parts of the space behind the wall, in open places, I stationed the people according to their families, with their swords, their spears, and their bows.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 14, 'After I looked these things over, I stood up and said to the nobles and the officials and the rest of the people, "Do not be afraid of them. Remember the LORD, who is great and awesome, and fight for your kin, your sons, your daughters, your wives, and your homes."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 15, 'When our enemies heard that their plot was known to us, and that God had frustrated it, we all returned to the wall, each to his work.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 16, 'From that day on, half of my servants worked on construction, and half held the spears, shields, bows, and body-armor; and the leaders posted themselves behind the whole house of Judah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 17, 'who were building the wall. The burden bearers carried their loads in such a way that each labored on the work with one hand and with the other held a weapon.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 18, 'And each of the builders had his sword strapped at his side while he built. The man who sounded the trumpet was beside me.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 19, 'And I said to the nobles, the officials, and the rest of the people, "The work is great and widely spread out, and we are separated far from one another on the wall.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 20, 'Rally to us wherever you hear the sound of the trumpet. Our God will fight for us."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 21, 'So we labored at the work, and half of them held the spears from break of dawn until the stars came out.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 22, 'I also said to the people at that time, "Let every man and his servant pass the night inside Jerusalem, so that they may be a guard for us by night and may labor by day."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 4, 23, 'So neither I nor my brothers nor my servants nor the men of the guard who followed me ever took off our clothes; each kept his weapon in his right hand.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 5, 1, 'Now there was a great outcry of the people and of their wives against their Jewish kin.', 'en', 'NRSV-CE', 'Nehemiah Deals with Oppression'),
(16, 'Neh', 'Nehemiah', 5, 2, 'For there were those who said, "With our sons and our daughters, we are many; we must get grain, so that we may eat and stay alive."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 3, 'There were also those who said, "We are having to pledge our fields, our vineyards, and our houses in order to get grain during the famine."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 4, 'And there were those who said, "We are having to borrow money on our fields and vineyards to pay the king"s tax.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 5, 'Now our flesh is the same as that of our kindred; our children are the same as their children; and yet we are forcing our sons and daughters to be slaves, and some of our daughters have been ravished; we are powerless, and our fields and vineyards now belong to others."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 6, 'I was very angry when I heard their outcry and these complaints.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 7, 'After thinking it over, I brought charges against the nobles and the officials; I said to them, "You are all taking interest from your own people." And I called a great assembly to deal with them,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 8, 'and said to them, "As far as we were able, we have bought back our Jewish kindred who had been sold to other nations; but now you are selling your own kin, who must then be bought back by us!" They were silent, and could not find a word to say.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 9, 'So I said, "The thing that you are doing is not good. Should you not walk in the fear of our God, to prevent the taunts of the nations our enemies?', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 10, 'Moreover I and my brothers and my servants are lending them money and grain. Let us stop this taking of interest.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 11, 'Restore to them, this very day, their fields, their vineyards, their olive orchards, and their houses, and the interest on money, grain, wine, and oil that you have been exacting from them."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 12, 'Then they said, "We will restore everything and demand nothing more from them. We will do as you say." And I called the priests, and made them take an oath to do as they had promised.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 13, 'I also shook out the fold of my garment and said, "So may God shake out everyone from house and from property who does not perform this promise. Thus may they be shaken out and emptied." And all the assembly said, "Amen," and praised the LORD. And the people did as they had promised.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 14, 'Moreover from the time that I was appointed to be their governor in the land of Judah, from the twentieth year to the thirty-second year of King Artaxerxes, twelve years, neither I nor my brothers ate the food allowance of the governor.', 'en', 'NRSV-CE', 'The Generosity of Nehemiah'),
(16, 'Neh', 'Nehemiah', 5, 15, 'The former governors who were before me laid heavy burdens on the people, and took food and wine from them, besides forty shekels of silver. Even their servants lorded it over the people. But I did not do so, because of the fear of God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 16, 'Indeed, I devoted myself to the work on this wall, and acquired no land; and all my servants were gathered there for the work.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 17, 'Moreover there were at my table one hundred fifty people, Jews and officials, besides those who came to us from the nations around us.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 18, 'Now that which was prepared for one day was one ox and six choice sheep; also fowls were prepared for me, and every ten days skins of wine in abundance; yet with all this I did not demand the food allowance of the governor, because of the heavy burden of labor on the people.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 5, 19, 'Remember for my good, O my God, all that I have done for this people.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 6, 1, 'Now when it was reported to Sanballat and Tobiah and to Geshem the Arab and to the rest of our enemies that I had built the wall and that there was no gap left in it (though up to that time I had not set up the doors in the gates),', 'en', 'NRSV-CE', 'Intrigues of Enemies Foiled'),
(16, 'Neh', 'Nehemiah', 6, 2, 'Sanballat and Geshem sent to me, saying, "Come and let us meet together in one of the villages in the plain of Ono." But they intended to do me harm.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 3, 'So I sent messengers to them, saying, "I am doing a great work and I cannot come down. Why should the work stop while I leave it to come down to you?"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 4, 'They sent to me four times in this way, and I answered them in the same manner.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 5, 'In the same way Sanballat for the fifth time sent his servant to me with an open letter in his hand.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 6, 'In it was written, "It is reported among the nations--and Geshem also says it--that you and the Jews intend to rebel; that is why you are building the wall; and according to this report you wish to become their king.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 7, 'You have also set up prophets to proclaim in Jerusalem concerning you, "There is a king in Judah!" And now it will be reported to the king according to these words. So come, therefore, and let us confer together."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 8, 'Then I sent to him, saying, "No such things as you say have been done; you are inventing them out of your own mind"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 9, '--for they all wanted to frighten us, thinking, "Their hands will drop from the work, and it will not be done." But now, O God, strengthen my hands.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 10, 'One day when I went into the house of Shemaiah son of Delaiah son of Mehetabel, who was confined to his house, he said, "Let us meet together in the house of God, within the temple, and let us close the doors of the temple, for they are coming to kill you; indeed, tonight they are coming to kill you."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 11, 'But I said, "Should a man like me run away? Would a man like me go into the temple to save his life? I will not go in!"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 12, 'Then I perceived and saw that God had not sent him at all, but he had pronounced the prophecy against me because Tobiah and Sanballat had hired him.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 13, 'He was hired for this purpose, to intimidate me and make me sin by acting in this way, and so they could give me a bad name, in order to taunt me.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 14, 'Remember Tobiah and Sanballat, O my God, according to these things that they did, and also the prophetess Noadiah and the rest of the prophets who wanted to make me afraid.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 15, 'So the wall was finished on the twenty-fifth day of the month Elul, in fifty-two days.', 'en', 'NRSV-CE', 'The Wall Completed'),
(16, 'Neh', 'Nehemiah', 6, 16, 'And when all our enemies heard of it, all the nations around us were afraid and fell greatly in their own esteem; for they perceived that this work had been accomplished with the help of our God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 17, 'Moreover in those days the nobles of Judah sent many letters to Tobiah, and Tobiah"s letters came to them.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 18, 'For many in Judah were bound by oath to him, because he was the son-in-law of Shecaniah son of Arah: and his son Jehohanan had married the daughter of Meshullam son of Berechiah.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 6, 19, 'Also they spoke of his good deeds in my presence, and reported my words to him. And Tobiah sent letters to intimidate me.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 7, 1, 'Now when the wall had been built and I had set up the doors, and the gatekeepers, the singers, and the Levites had been appointed,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 7, 2, 'I gave my brother Hanani charge over Jerusalem, along with Hananiah the commander of the citadel--for he was a faithful man and feared God more than many.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 7, 3, 'And I said to them, "The gates of Jerusalem are not to be opened until the sun is hot; while the gatekeepers are still standing guard, let them shut and bar the doors. Appoint guards from among the inhabitants of Jerusalem, some at their watch posts, and others before their own houses."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 7, 4, 'The city was wide and large, but the people within it were few and no houses had been built.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 7, 5, 'Then my God put it into my mind to assemble the nobles and the officials and the people to be enrolled by genealogy. And I found the book of the genealogy of those who were the first to come back, and I found the following written in it:', 'en', 'NRSV-CE', 'Lists of the Returned Exiles'),
(16, 'Neh', 'Nehemiah', 7, 6, 'These are the people of the province who came up out of the captivity of those exiles whom King Nebuchadnezzar of Babylon had carried into exile; they returned to Jerusalem and Judah, each to his town.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 7, 7, 'They came with Zerubbabel, Jeshua, Nehemiah, Azariah, Raamiah, Nahamani, Mordecai, Bilshan, Mispereth, Bigvai, Nehum, Baanah.
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 8, 1, 'all the people gathered together into the square before the Water Gate. They told the scribe Ezra to bring the book of the law of Moses, which the LORD had given to Israel.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 2, 'Accordingly, the priest Ezra brought the law before the assembly, both men and women and all who could hear with understanding. This was on the first day of the seventh month.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 3, 'He read from it facing the square before the Water Gate from early morning until midday, in the presence of the men and the women and those who could understand; and the ears of all the people were attentive to the book of the law.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 4, 'The scribe Ezra stood on a wooden platform that had been made for the purpose; and beside him stood Mattithiah, Shema, Anaiah, Uriah, Hilkiah, and Maaseiah on his right hand; and Pedaiah, Mishael, Malchijah, Hashum, Hash-baddanah, Zechariah, and Meshullam on his left hand.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 5, 'And Ezra opened the book in the sight of all the people, for he was standing above all the people; and when he opened it, all the people stood up.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 6, 'Then Ezra blessed the LORD, the great God, and all the people answered, "Amen, Amen," lifting up their hands. Then they bowed their heads and worshiped the LORD with their faces to the ground.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 7, 'Also Jeshua, Bani, Sherebiah, Jamin, Akkub, Shabbethai, Hodiah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, Pelaiah, the Levites, helped the people to understand the law, while the people remained in their places.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 8, 'So they read from the book, from the law of God, with interpretation. They gave the sense, so that the people understood the reading.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 9, 'And Nehemiah, who was the governor, and Ezra the priest and scribe, and the Levites who taught the people said to all the people, "This day is holy to the LORD your God; do not mourn or weep." For all the people wept when they heard the words of the law.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 10, 'Then he said to them, "Go your way, eat the fat and drink sweet wine and send portions of them to those for whom nothing is prepared, for this day is holy to our LORD; and do not be grieved, for the joy of the LORD is your strength."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 11, 'So the Levites stilled all the people, saying, "Be quiet, for this day is holy; do not be grieved."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 12, 'And all the people went their way to eat and drink and to send portions and to make great rejoicing, because they had understood the words that were declared to them.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 13, 'On the second day the heads of ancestral houses of all the people, with the priests and the Levites, came together to the scribe Ezra in order to study the words of the law.', 'en', 'NRSV-CE', 'The Festival of Booths Celebrated'),
(16, 'Neh', 'Nehemiah', 8, 14, 'And they found it written in the law, which the LORD had commanded by Moses, that the people of Israel should live in booths during the festival of the seventh month,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 15, 'and that they should publish and proclaim in all their towns and in Jerusalem as follows, "Go out to the hills and bring branches of olive, wild olive, myrtle, palm, and other leafy trees to make booths, as it is written."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 16, 'So the people went out and brought them, and made booths for themselves, each on the roofs of their houses, and in their courts and in the courts of the house of God, and in the square at the Water Gate and in the square at the Gate of Ephraim.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 17, 'And all the assembly of those who had returned from the captivity made booths and lived in them; for from the days of Jeshua son of Nun to that day the people of Israel had not done so. And there was very great rejoicing.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 8, 18, 'And day by day, from the first day to the last day, he read from the book of the law of God. They kept the festival seven days; and on the eighth day there was a solemn assembly, according to the ordinance.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 9, 1, 'Now on the twenty-fourth day of this month the people of Israel were assembled with fasting and in sackcloth, and with earth on their heads.', 'en', 'NRSV-CE', 'National Confession'),
(16, 'Neh', 'Nehemiah', 9, 2, 'Then those of Israelite descent separated themselves from all foreigners, and stood and confessed their sins and the iniquities of their ancestors.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 3, 'They stood up in their place and read from the book of the law of the LORD their God for a fourth part of the day, and for another fourth they made confession and worshiped the LORD their God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 4, 'Then Jeshua, Bani, Kadmiel, Shebaniah, Bunni, Sherebiah, Bani, and Chenani stood on the stairs of the Levites and cried out with a loud voice to the LORD their God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 5, 'Then the Levites, Jeshua, Kadmiel, Bani, Hashabneiah, Sherebiah, Hodiah, Shebaniah, and Pethahiah, said, "Stand up and bless the LORD your God from everlasting to everlasting. Blessed be your glorious name, which is exalted above all blessing and praise."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 6, 'And Ezra said: "You are the LORD, you alone; you have made heaven, the heaven of heavens, with all their host, the earth and all that is on it, the seas and all that is in them. To all of them you give life, and the host of heaven worships you.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 7, 'You are the LORD, the God who chose Abram and brought him out of Ur of the Chaldeans and gave him the name Abraham;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 8, 'and you found his heart faithful before you, and made with him a covenant to give to his descendants the land of the Canaanite, the Hittite, the Amorite, the Perizzite, the Jebusite, and the Girgashite; and you have fulfilled your promise, for you are righteous.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 9, '"And you saw the distress of our ancestors in Egypt and heard their cry at the Red Sea.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 10, 'You performed signs and wonders against Pharaoh and all his servants and all the people of his land, for you knew that they acted insolently against our ancestors. You made a name for yourself, which remains to this day.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 11, 'And you divided the sea before them, so that they passed through the sea on dry land, but you threw their pursuers into the depths, like a stone into mighty waters.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 12, 'Moreover, you led them by day with a pillar of cloud, and by night with a pillar of fire, to give them light on the way in which they should go.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 13, 'You came down also upon Mount Sinai, and spoke with them from heaven, and gave them right ordinances and true laws, good statutes and commandments,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 14, 'and you made known your holy sabbath to them and gave them commandments and statutes and a law through your servant Moses.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 15, 'For their hunger you gave them bread from heaven, and for their thirst you brought water for them out of the rock, and you told them to go in to possess the land that you swore to give them.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 16, '"But they and our ancestors acted presumptuously and stiffened their necks and did not obey your commandments;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 17, 'they refused to obey, and were not mindful of the wonders that you performed among them; but they stiffened their necks and determined to return to their slavery in Egypt. But you are a God ready to forgive, gracious and merciful, slow to anger and abounding in steadfast love, and you did not forsake them.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 18, 'Even when they had cast an image of a calf for themselves and said, "This is your God who brought you up out of Egypt," and had committed great blasphemies,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 19, 'you in your great mercies did not forsake them in the wilderness; the pillar of cloud that led them in the way did not leave them by day, nor the pillar of fire by night that gave them light on the way by which they should go.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 20, 'You gave your good spirit to instruct them, and did not withhold your manna from their mouths, and gave them water for their thirst.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 21, 'Forty years you sustained them in the wilderness so that they lacked nothing; their clothes did not wear out and their feet did not swell.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 22, 'And you gave them kingdoms and peoples, and allotted to them every corner, so they took possession of the land of King Sihon of Heshbon and the land of King Og of Bashan.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 23, 'You multiplied their descendants like the stars of heaven, and brought them into the land that you had told their ancestors to enter and possess.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 24, 'So the descendants went in and possessed the land, and you subdued before them the inhabitants of the land, the Canaanites, and gave them into their hands, with their kings and the peoples of the land, to do with them as they pleased.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 25, 'And they captured fortress cities and a rich land, and took possession of houses filled with all sorts of goods, hewn cisterns, vineyards, olive orchards, and fruit trees in abundance; so they ate, and were filled and became fat, and delighted themselves in your great goodness.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 26, '"Nevertheless they were disobedient and rebelled against you and cast your law behind their backs and killed your prophets, who had warned them in order to turn them back to you, and they committed great blasphemies.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 27, 'Therefore you gave them into the hands of their enemies, who made them suffer. Then in the time of their suffering they cried out to you and you heard them from heaven, and according to your great mercies you gave them saviors who saved them from the hands of their enemies.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 28, 'But after they had rest, they again did evil before you, and you abandoned them to the hands of their enemies, so that they had dominion over them; yet when they turned and cried to you, you heard from heaven, and many times you rescued them according to your mercies.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 29, 'And you warned them in order to turn them back to your law. Yet they acted presumptuously and did not obey your commandments, but sinned against your ordinances, by the observance of which a person shall live. They turned a stubborn shoulder and stiffened their neck and would not obey.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 30, 'Many years you were patient with them, and warned them by your spirit through your prophets; yet they would not listen. Therefore you handed them over to the peoples of the lands.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 31, 'Nevertheless, in your great mercies you did not make an end of them or forsake them, for you are a gracious and merciful God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 32, '"Now therefore, our God--the great and mighty and awesome God, keeping covenant and steadfast love--do not treat lightly all the hardship that has come upon us, upon our kings, our officials, our priests, our prophets, our ancestors, and all your people, since the time of the kings of Assyria until today.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 33, 'You have been just in all that has come upon us, for you have dealt faithfully and we have acted wickedly;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 34, 'our kings, our officials, our priests, and our ancestors have not kept your law or heeded the commandments and the warnings that you gave them.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 35, 'Even in their own kingdom, and in the great goodness you bestowed on them, and in the large and rich land that you set before them, they did not serve you and did not turn from their wicked works.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 36, 'Here we are, slaves to this day--slaves in the land that you gave to our ancestors to enjoy its fruit and its good gifts.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 37, 'Its rich yield goes to the kings whom you have set over us because of our sins; they have power also over our bodies and over our livestock at their pleasure, and we are in great distress."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 9, 38, 'Because of all this we make a firm agreement in writing, and on that sealed document are inscribed the names of our officials, our Levites, and our priests.', 'en', 'NRSV-CE', 'Those Who Signed the Covenant');
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 10, 1, 'Upon the sealed document are the names of Nehemiah the governor, son of Hacaliah, and Zedekiah;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 2, 'Seraiah, Azariah, Jeremiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 3, 'Pashhur, Amariah, Malchijah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 4, 'Hattush, Shebaniah, Malluch,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 5, 'Harim, Meremoth, Obadiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 6, 'Daniel, Ginnethon, Baruch,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 7, 'Meshullam, Abijah, Mijamin,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 8, 'Maaziah, Bilgai, Shemaiah; these are the priests.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 9, 'And the Levites: Jeshua son of Azaniah, Binnui of the sons of Henadad, Kadmiel;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 10, 'and their associates, Shebaniah, Hodiah, Kelita, Pelaiah, Hanan,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 11, 'Mica, Rehob, Hashabiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 12, 'Zaccur, Sherebiah, Shebaniah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 13, 'Hodiah, Bani, Beninu.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 14, 'The leaders of the people: Parosh, Pahath-moab, Elam, Zattu, Bani,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 15, 'Bunni, Azgad, Bebai,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 16, 'Adonijah, Bigvai, Adin,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 17, 'Ater, Hezekiah, Azzur,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 18, 'Hodiah, Hashum, Bezai,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 19, 'Hariph, Anathoth, Nebai,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 20, 'Magpiash, Meshullam, Hezir,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 21, 'Meshezabel, Zadok, Jaddua,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 22, 'Pelatiah, Hanan, Anaiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 23, 'Hoshea, Hananiah, Hasshub,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 24, 'Hallohesh, Pilha, Shobek,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 25, 'Rehum, Hashabnah, Maaseiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 26, 'Ahiah, Hanan, Anan,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 27, 'Malluch, Harim, and Baanah.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 28, 'The rest of the people, the priests, the Levites, the gatekeepers, the singers, the temple servants, and all who have separated themselves from the peoples of the lands to adhere to the law of God, their wives, their sons, their daughters, all who have knowledge and understanding,', 'en', 'NRSV-CE', 'Summary of the Covenant'),
(16, 'Neh', 'Nehemiah', 10, 29, 'join with their kin, their nobles, and enter into a curse and an oath to walk in God"s law, which was given by Moses the servant of God, and to observe and do all the commandments of the LORD our Lord and his ordinances and his statutes.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 30, 'We will not give our daughters to the peoples of the land or take their daughters for our sons;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 31, 'and if the peoples of the land bring in merchandise or any grain on the sabbath day to sell, we will not buy it from them on the sabbath or on a holy day; and we will forego the crops of the seventh year and the exaction of every debt.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 32, 'We also lay on ourselves the obligation to charge ourselves yearly one-third of a shekel for the service of the house of our God:', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 33, 'for the rows of bread, the regular grain offering, the regular burnt offering, the sabbaths, the new moons, the appointed festivals, the sacred donations, and the sin offerings to make atonement for Israel, and for all the work of the house of our God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 34, 'We have also cast lots among the priests, the Levites, and the people, for the wood offering, to bring it into the house of our God, by ancestral houses, at appointed times, year by year, to burn on the altar of the LORD our God, as it is written in the law.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 35, 'We obligate ourselves to bring the first fruits of our soil and the first fruits of all fruit of every tree, year by year, to the house of the LORD;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 36, 'also to bring to the house of our God, to the priests who minister in the house of our God, the firstborn of our sons and of our livestock, as it is written in the law, and the firstlings of our herds and of our flocks;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 37, 'and to bring the first of our dough, and our contributions, the fruit of every tree, the wine and the oil, to the priests, to the chambers of the house of our God; and to bring to the Levites the tithes from our soil, for it is the Levites who collect the tithes in all our rural towns.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 38, 'And the priest, the descendant of Aaron, shall be with the Levites when the Levites receive the tithes; and the Levites shall bring up a tithe of the tithes to the house of our God, to the chambers of the storehouse.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 10, 39, 'For the people of Israel and the sons of Levi shall bring the contribution of grain, wine, and oil to the storerooms where the vessels of the sanctuary are, and where the priests that minister, and the gatekeepers and the singers are. We will not neglect the house of our God.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 11, 1, 'Now the leaders of the people lived in Jerusalem; and the rest of the people cast lots to bring one out of ten to live in the holy city Jerusalem, while nine-tenths remained in the other towns.', 'en', 'NRSV-CE', 'Population of the City Increased'),
(16, 'Neh', 'Nehemiah', 11, 2, 'And the people blessed all those who willingly offered to live in Jerusalem.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 3, 'These are the leaders of the province who lived in Jerusalem; but in the towns of Judah all lived on their property in their towns: Israel, the priests, the Levites, the temple servants, and the descendants of Solomon"s servants.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 4, 'And in Jerusalem lived some of the Judahites and of the Benjaminites. Of the Judahites: Athaiah son of Uzziah son of Zechariah son of Amariah son of Shephatiah son of Mahalalel, of the descendants of Perez;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 5, 'and Maaseiah son of Baruch son of Col-hozeh son of Hazaiah son of Adaiah son of Joiarib son of Zechariah son of the Shilonite.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 6, 'All the descendants of Perez who lived in Jerusalem were four hundred sixty-eight valiant warriors.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 7, 'And these are the Benjaminites: Sallu son of Meshullam son of Joed son of Pedaiah son of Kolaiah son of Maaseiah son of Ithiel son of Jeshaiah.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 8, 'And his brothers Gabbai, Sallai: nine hundred twenty-eight.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 9, 'Joel son of Zichri was their overseer; and Judah son of Hassenuah was second in charge of the city.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 10, 'Of the priests: Jedaiah son of Joiarib, Jachin,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 11, 'Seraiah son of Hilkiah son of Meshullam son of Zadok son of Meraioth son of Ahitub, officer of the house of God,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 12, 'and their associates who did the work of the house, eight hundred twenty-two; and Adaiah son of Jeroham son of Pelaliah son of Amzi son of Zechariah son of Pashhur son of Malchijah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 13, 'and his associates, heads of ancestral houses, two hundred forty-two; and Amashsai son of Azarel son of Ahzai son of Meshillemoth son of Immer,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 14, 'and their associates, valiant warriors, one hundred twenty-eight; their overseer was Zabdiel son of Haggedolim.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 15, 'And of the Levites: Shemaiah son of Hasshub son of Azrikam son of Hashabiah son of Bunni;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 16, 'and Shabbethai and Jozabad, of the leaders of the Levites, who were over the outside work of the house of God;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 17, 'and Mattaniah son of Mica son of Zabdi son of Asaph, who was the leader to begin the thanksgiving in prayer, and Bakbukiah, the second among his associates; and Abda son of Shammua son of Galal son of Jeduthun.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 18, 'All the Levites in the holy city were two hundred eighty-four.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 19, 'The gatekeepers, Akkub, Talmon and their associates, who kept watch at the gates, were one hundred seventy-two.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 20, 'And the rest of Israel, and of the priests and the Levites, were in all the towns of Judah, all of them in their inheritance.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 21, 'But the temple servants lived on Ophel; and Ziha and Gishpa were over the temple servants.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 22, 'The overseer of the Levites in Jerusalem was Uzzi son of Bani son of Hashabiah son of Mattaniah son of Mica, of the descendants of Asaph, the singers, in charge of the work of the house of God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 23, 'For there was a command from the king concerning them, and a settled provision for the singers, as was required every day.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 24, 'And Pethahiah son of Meshezabel, of the descendants of Zerah son of Judah, was at the king"s hand in all matters concerning the people.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 25, 'And as for the villages, with their fields, some of the people of Judah lived in Kiriath-arba and its villages, and in Dibon and its villages, and in Jekabzeel and its villages,', 'en', 'NRSV-CE', 'Villages outside Jerusalem'),
(16, 'Neh', 'Nehemiah', 11, 26, 'and in Jeshua and in Moladah and Beth-pelet,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 27, 'in Hazar-shual, in Beer-sheba and its villages,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 28, 'in Ziklag, in Meconah and its villages,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 29, 'in En-rimmon, in Zorah, in Jarmuth,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 30, 'Zanoah, Adullam, and their villages, Lachish and its fields, and Azekah and its villages. So they camped from Beer-sheba to the valley of Hinnom.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 31, 'The people of Benjamin also lived from Geba onward, at Michmash, Aija, Bethel and its villages,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 32, 'Anathoth, Nob, Ananiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 33, 'Hazor, Ramah, Gittaim,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 34, 'Hadid, Zeboim, Neballat,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 35, 'Lod, and Ono, the valley of artisans.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 11, 36, 'And certain divisions of the Levites in Judah were joined to Benjamin.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 12, 1, 'These are the priests and the Levites who came up with Zerubbabel son of Shealtiel, and Jeshua: Seraiah, Jeremiah, Ezra,', 'en', 'NRSV-CE', 'A List of Priests and Levites'),
(16, 'Neh', 'Nehemiah', 12, 2, 'Amariah, Malluch, Hattush,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 3, 'Shecaniah, Rehum, Meremoth,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 4, 'Iddo, Ginnethoi, Abijah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 5, 'Mijamin, Maadiah, Bilgah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 6, 'Shemaiah, Joiarib, Jedaiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 7, 'Sallu, Amok, Hilkiah, Jedaiah. These were the leaders of the priests and of their associates in the days of Jeshua.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 8, 'And the Levites: Jeshua, Binnui, Kadmiel, Sherebiah, Judah, and Mattaniah, who with his associates was in charge of the songs of thanksgiving.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 9, 'And Bakbukiah and Unno their associates stood opposite them in the service.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 10, 'Jeshua was the father of Joiakim, Joiakim the father of Eliashib, Eliashib the father of Joiada,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 11, 'Joiada the father of Jonathan, and Jonathan the father of Jaddua.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 12, 'In the days of Joiakim the priests, heads of ancestral houses, were: of Seraiah, Meraiah; of Jeremiah, Hananiah;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 13, 'of Ezra, Meshullam; of Amariah, Jehohanan;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 14, 'of Malluchi, Jonathan; of Shebaniah, Joseph;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 15, 'of Harim, Adna; of Meraioth, Helkai;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 16, 'of Iddo, Zechariah; of Ginnethon, Meshullam;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 17, 'of Abijah, Zichri; of Miniamin, of Moadiah, Piltai;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 18, 'of Bilgah, Shammua; of Shemaiah, Jehonathan;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 19, 'of Joiarib, Mattenai; of Jedaiah, Uzzi;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 20, 'of Sallai, Kallai; of Amok, Eber;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 21, 'of Hilkiah, Hashabiah; of Jedaiah, Nethanel.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 22, 'As for the Levites, in the days of Eliashib, Joiada, Johanan, and Jaddua, there were recorded the heads of ancestral houses; also the priests until the reign of Darius the Persian.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 23, 'The Levites, heads of ancestral houses, were recorded in the Book of the Annals until the days of Johanan son of Eliashib.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 24, 'And the leaders of the Levites: Hashabiah, Sherebiah, and Jeshua son of Kadmiel, with their associates over against them, to praise and to give thanks, according to the commandment of David the man of God, section opposite to section.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 25, 'Mattaniah, Bakbukiah, Obadiah, Meshullam, Talmon, and Akkub were gatekeepers standing guard at the storehouses of the gates.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 26, 'These were in the days of Joiakim son of Jeshua son of Jozadak, and in the days of the governor Nehemiah and of the priest Ezra, the scribe.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 27, 'Now at the dedication of the wall of Jerusalem they sought out the Levites in all their places, to bring them to Jerusalem to celebrate the dedication with rejoicing, with thanksgivings and with singing, with cymbals, harps, and lyres.', 'en', 'NRSV-CE', 'Dedication of the City Wall'),
(16, 'Neh', 'Nehemiah', 12, 28, 'The companies of the singers gathered together from the circuit around Jerusalem and from the villages of the Netophathites;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 29, 'also from Beth-gilgal and from the region of Geba and Azmaveth; for the singers had built for themselves villages around Jerusalem.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 30, 'And the priests and the Levites purified themselves; and they purified the people and the gates and the wall.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 31, 'Then I brought the leaders of Judah up onto the wall, and appointed two great companies that gave thanks and went in procession. One went to the right on the wall to the Dung Gate;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 32, 'and after them went Hoshaiah and half the officials of Judah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 33, 'and Azariah, Ezra, Meshullam,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 34, 'Judah, Benjamin, Shemaiah, and Jeremiah,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 35, 'and some of the young priests with trumpets: Zechariah son of Jonathan son of Shemaiah son of Mattaniah son of Micaiah son of Zaccur son of Asaph;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 36, 'and his kindred, Shemaiah, Azarel, Milalai, Gilalai, Maai, Nethanel, Judah, and Hanani, with the musical instruments of David the man of God; and the scribe Ezra went in front of them.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 37, 'At the Fountain Gate, in front of them, they went straight up by the stairs of the city of David, at the ascent of the wall, above the house of David, to the Water Gate on the east.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 38, 'The other company of those who gave thanks went to the left, and I followed them with half of the people on the wall, above the Tower of the Ovens, to the Broad Wall,', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 39, 'and above the Gate of Ephraim, and by the Old Gate, and by the Fish Gate and the Tower of Hananel and the Tower of the Hundred, to the Sheep Gate; and they came to a halt at the Gate of the Guard.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 40, 'So both companies of those who gave thanks stood in the house of God, and I and half of the officials with me;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 41, 'and the priests Eliakim, Maaseiah, Miniamin, Micaiah, Elioenai, Zechariah, and Hananiah, with trumpets;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 42, 'and Maaseiah, Shemaiah, Eleazar, Uzzi, Jehohanan, Malchijah, Elam, and Ezer. And the singers sang with Jezrahiah as their leader.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 43, 'They offered great sacrifices that day and rejoiced, for God had made them rejoice with great joy; the women and children also rejoiced. The joy of Jerusalem was heard far away.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 44, 'On that day men were appointed over the chambers for the stores, the contributions, the first fruits, and the tithes, to gather into them the portions required by the law for the priests and for the Levites from the fields belonging to the towns; for Judah rejoiced over the priests and the Levites who ministered.', 'en', 'NRSV-CE', 'Temple Responsibilities'),
(16, 'Neh', 'Nehemiah', 12, 45, 'They performed the service of their God and the service of purification, as did the singers and the gatekeepers, according to the command of David and his son Solomon.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 46, 'For in the days of David and Asaph long ago there was a leader of the singers, and there were songs of praise and thanksgiving to God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 12, 47, 'In the days of Zerubbabel and in the days of Nehemiah all Israel gave the daily portions for the singers and the gatekeepers. They set apart that which was for the Levites; and the Levites set apart that which was for the descendants of Aaron.', 'en', 'NRSV-CE', NULL);
INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation, title) VALUES
(16, 'Neh', 'Nehemiah', 13, 1, 'On that day they read from the book of Moses in the hearing of the people; and in it was found written that no Ammonite or Moabite should ever enter the assembly of God,', 'en', 'NRSV-CE', 'Foreigners Separated from Israel'),
(16, 'Neh', 'Nehemiah', 13, 2, 'because they did not meet the Israelites with bread and water, but hired Balaam against them to curse them--yet our God turned the curse into a blessing.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 3, 'When the people heard the law, they separated from Israel all those of foreign descent.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 4, 'Now before this, the priest Eliashib, who was appointed over the chambers of the house of our God, and who was related to Tobiah,', 'en', 'NRSV-CE', 'The Reforms of Nehemiah'),
(16, 'Neh', 'Nehemiah', 13, 5, 'prepared for Tobiah a large room where they had previously put the grain offering, the frankincense, the vessels, and the tithes of grain, wine, and oil, which were given by commandment to the Levites, singers, and gatekeepers, and the contributions for the priests.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 6, 'While this was taking place I was not in Jerusalem, for in the thirty-second year of King Artaxerxes of Babylon I went to the king. After some time I asked leave of the king', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 7, 'and returned to Jerusalem. I then discovered the wrong that Eliashib had done on behalf of Tobiah, preparing a room for him in the courts of the house of God.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 8, 'And I was very angry, and I threw all the household furniture of Tobiah out of the room.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 9, 'Then I gave orders and they cleansed the chambers, and I brought back the vessels of the house of God, with the grain offering and the frankincense.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 10, 'I also found out that the portions of the Levites had not been given to them; so that the Levites and the singers, who had conducted the service, had gone back to their fields.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 11, 'So I remonstrated with the officials and said, "Why is the house of God forsaken?" And I gathered them together and set them in their stations.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 12, 'Then all Judah brought the tithe of the grain, wine, and oil into the storehouses.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 13, 'And I appointed as treasurers over the storehouses the priest Shelemiah, the scribe Zadok, and Pedaiah of the Levites, and as their assistant Hanan son of Zaccur son of Mattaniah, for they were considered faithful; and their duty was to distribute to their associates.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 14, 'Remember me, O my God, concerning this, and do not wipe out my good deeds that I have done for the house of my God and for his service.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 15, 'In those days I saw in Judah people treading wine presses on the sabbath, and bringing in heaps of grain and loading them on donkeys; and also wine, grapes, figs, and all kinds of burdens, which they brought into Jerusalem on the sabbath day; and I warned them at that time against selling food.', 'en', 'NRSV-CE', 'Sabbath Reforms Begun'),
(16, 'Neh', 'Nehemiah', 13, 16, 'Tyrians also, who lived in the city, brought in fish and all kinds of merchandise and sold them on the sabbath to the people of Judah, and in Jerusalem.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 17, 'Then I remonstrated with the nobles of Judah and said to them, "What is this evil thing that you are doing, profaning the sabbath day?', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 18, 'Did not your ancestors act in this way, and did not our God bring all this disaster on us and on this city? Yet you bring more wrath on Israel by profaning the sabbath."', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 19, 'When it began to be dark at the gates of Jerusalem before the sabbath, I commanded that the doors should be shut and gave orders that they should not be opened until after the sabbath. And I set some of my servants over the gates, to prevent any burden from being brought in on the sabbath day.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 20, 'Then the merchants and sellers of all kinds of merchandise spent the night outside Jerusalem once or twice.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 21, 'But I warned them and said to them, "Why do you spend the night in front of the wall? If you do so again, I will lay hands on you." From that time on they did not come on the sabbath.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 22, 'And I commanded the Levites that they should purify themselves and come and guard the gates, to keep the sabbath day holy. Remember this also in my favor, O my God, and spare me according to the greatness of your steadfast love.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 23, 'In those days also I saw Jews who had married women of Ashdod, Ammon, and Moab;', 'en', 'NRSV-CE', 'Mixed Marriages Condemned'),
(16, 'Neh', 'Nehemiah', 13, 24, 'and half of their children spoke the language of Ashdod, and they could not speak the language of Judah, but spoke the language of various peoples.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 25, 'And I contended with them and cursed them and beat some of them and pulled out their hair; and I made them take an oath in the name of God, saying, "You shall not give your daughters to their sons, or take their daughters for your sons or for yourselves.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 26, 'Did not King Solomon of Israel sin on account of such women? Among the many nations there was no king like him, and he was beloved by his God, and God made him king over all Israel; nevertheless, foreign women made even him to sin.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 27, 'Shall we then listen to you and do all this great evil and act treacherously against our God by marrying foreign women?"', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 28, 'And one of the sons of Jehoiada, son of the high priest Eliashib, was the son-in-law of Sanballat the Horonite; I chased him away from me.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 29, 'Remember them, O my God, because they have defiled the priesthood, the covenant of the priests and the Levites.', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 30, 'Thus I cleansed them from everything foreign, and I established the duties of the priests and Levites, each in his work;', 'en', 'NRSV-CE', NULL),
(16, 'Neh', 'Nehemiah', 13, 31, 'and I provided for the wood offering, at appointed times, and for the first fruits. Remember me, O my God, for good.', 'en', 'NRSV-CE', NULL);
